using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

builder.Services.AddChatClient(b => b
    .UseOpenAIChatClient(
        modelId: builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18",
        openAIClient: new OpenAIClient(
            builder.Configuration["AI:ApiKey"]
                ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
                ?? throw new InvalidOperationException(
                    "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable."))));

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. When given a topic, use the available tools to:
        1. Search the web for relevant information (multiple searches for breadth).
        2. Take notes on key findings as you go.
        3. Once you have enough information, produce a final summary of your research.
        Be thorough but concise. Always take notes before summarizing.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics using web search and note-taking.",
    tools: [AIFunctionFactory.Create(SearchWeb), AIFunctionFactory.Create(TakeNote)]);

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
});

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    options: runOptions);

Console.WriteLine("=== Research Summary ===\n");
Console.WriteLine(response.Messages.LastOrDefault()?.Text ?? "No response generated.");
Console.WriteLine();

// --- Tool definitions ---

[Description("Searches the web for information on a query. Returns a list of relevant results with titles and snippets.")]
static string SearchWeb(
    [Description("The search query to look up on the web")] string query)
{
    // Simulated web search results for demonstration purposes.
    // In production, replace with a real search API (e.g., Bing Search, Google Custom Search).
    Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");

    return $$"""
        Search results for "{{query}}":
        1. Title: "{{query}} - Overview and Key Concepts"
           Snippet: This comprehensive guide covers the fundamental aspects of {{query}}, including its history, current state, and future directions.
           URL: https://example.com/article1

        2. Title: "Latest Developments in {{query}}"
           Snippet: Recent advances have transformed how we think about {{query}}. Key breakthroughs include improved methodologies and broader applications.
           URL: https://example.com/article2

        3. Title: "{{query}}: Expert Analysis and Opinions"
           Snippet: Leading experts weigh in on the implications of {{query}} for industry and society, highlighting both opportunities and challenges.
           URL: https://example.com/article3
        """;
}

static readonly List<string> _notes = [];

[Description("Takes a note to remember important findings during research. Use this to record key facts, quotes, or insights as you discover them.")]
static string TakeNote(
    [Description("The note content to save")] string note)
{
    _notes.Add(note);
    Console.WriteLine($"  [Tool] Note taken: \"{note[..Math.Min(note.Length, 80)]}...\"");
    return $"Note saved successfully. You now have {_notes.Count} note(s).";
}

