using System.ComponentModel;

/// <summary>
/// Provides web search and note-taking tools for the research agent.
/// </summary>
public sealed class ResearchTools
{
    private readonly List<string> _notes = [];

    [Description("Searches the web for information on a query. Returns a list of relevant results with titles and snippets.")]
    public string SearchWeb(
        [Description("The search query to look up on the web")] string query)
    {
        // Simulated web search results — replace with a real search API (e.g., Bing Search) in production.
        Console.WriteLine($"  [Tool] Searching web for: \"{query}\"");

        return $$"""
            Search results for "{{query}}":
            1. Title: "{{query}} - Overview and Key Concepts"
               Snippet: This comprehensive guide covers the fundamental aspects of {{query}}, including its history, current state, and future directions.
               URL: https://example.com/article1

            2. Title: "Latest Developments in {{query}}"
               Snippet: Recent advances have transformed how we think about {{query}}. Key breakthroughs include improved methodologies and broader applications.
               URL: https://example.com/article2

            3. Title: "{{query}}: Expert Analysis and Opinions"
               Snippet: Leading experts weigh in on the implications of {{query}} for industry and society, highlighting both opportunities and challenges.
               URL: https://example.com/article3
            """;
    }

    [Description("Takes a note to remember important findings during research. Use this to record key facts, quotes, or insights as you discover them.")]
    public string TakeNote(
        [Description("The note content to save")] string note)
    {
        _notes.Add(note);
        var preview = note.Length > 80 ? note[..80] + "..." : note;
        Console.WriteLine($"  [Tool] Note taken: \"{preview}\"");
        return $"Note saved successfully. You now have {_notes.Count} note(s).";
    }
}

