using System.ComponentModel;
using Microsoft.Agents.AI;
using Microsoft.Extensions.AI;
using Microsoft.Extensions.DependencyInjection;
using Microsoft.Extensions.Hosting;
using OpenAI;

var builder = Host.CreateApplicationBuilder(args);

var apiKey = builder.Configuration["AI:ApiKey"]
    ?? Environment.GetEnvironmentVariable("OPENAI_API_KEY")
    ?? throw new InvalidOperationException(
        "Set AI:ApiKey in configuration or OPENAI_API_KEY environment variable.");

var modelId = builder.Configuration["AI:ModelId"] ?? "gpt-4o-mini-2024-07-18";

builder.Services.AddChatClient(sp =>
    new OpenAIChatClient(new OpenAIClient(apiKey).GetChatClient(modelId)));

using var host = builder.Build();

var chatClient = host.Services.GetRequiredService<IChatClient>();
var tools = new ResearchTools();

var agent = new ChatClientAgent(
    chatClient,
    instructions: """
        You are a research agent. When given a topic, use the available tools to:
        1. Search the web for relevant information (multiple searches for breadth).
        2. Take notes on key findings as you go.
        3. Once you have enough information, produce a final summary of your research.
        Be thorough but concise. Always take notes before summarizing.
        """,
    name: "ResearchAgent",
    description: "An agent that researches topics using web search and note-taking.",
    tools: [AIFunctionFactory.Create(tools.SearchWeb), AIFunctionFactory.Create(tools.TakeNote)]);

Console.Write("Enter a research topic: ");
var topic = Console.ReadLine();
if (string.IsNullOrWhiteSpace(topic))
{
    Console.WriteLine("No topic provided. Exiting.");
    return;
}

Console.WriteLine($"\nResearching: {topic}\n");

var runOptions = new ChatClientAgentRunOptions(new ChatOptions
{
    Temperature = 0f,
    MaxOutputTokens = 4096,
});

var response = await agent.RunAsync(
    $"Research the following topic and provide a comprehensive summary: {topic}",
    options: runOptions);

Console.WriteLine("=== Research Summary ===\n");
Console.WriteLine(response.Messages.LastOrDefault()?.Text ?? "No response generated.");
Console.WriteLine();

